use std::collections::BTreeMap
use std::fs

fn bal(m: BTreeMap<string, int>, name: string) -> Option<int> {
    m.get(name).copied()
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut accts: BTreeMap<string, int> = BTreeMap::new()
    for line in text.lines() {
        let parts: Vec<string> = line.split_whitespace().map(|s| s.to_string()).collect()
        if parts.len() == 0 {
            continue
        }
        let cmd = parts[0].clone()
        if cmd == "open" {
            let name = parts[1].clone()
            let amt: int = parts[2].parse::<int>().unwrap_or(0)
            if amt < 0 {
                println("error: invalid amount")
            } else if accts.contains_key(name) {
                println("error: duplicate account")
            } else {
                accts.insert(name, amt)
                println("ok")
            }
        } else if cmd == "balance" {
            let name = parts[1].clone()
            match bal(accts.clone(), name.clone()) {
                Some(b) => println("${b}"),
                None => println("error: unknown account ${name}"),
            }
        } else if cmd == "deposit" || cmd == "withdraw" {
            let name = parts[1].clone()
            let amt: int = parts[2].parse::<int>().unwrap_or(0)
            if amt <= 0 {
                println("error: invalid amount")
            } else {
                match bal(accts.clone(), name.clone()) {
                    None => println("error: unknown account ${name}"),
                    Some(b) => {
                        if cmd == "deposit" {
                            accts.insert(name, b + amt)
                            println("ok")
                        } else if amt > b {
                            println("error: insufficient funds")
                        } else {
                            accts.insert(name, b - amt)
                            println("ok")
                        }
                    }
                }
            }
        } else if cmd == "transfer" {
            let from = parts[1].clone()
            let to = parts[2].clone()
            let amt: int = parts[3].parse::<int>().unwrap_or(0)
            if amt <= 0 {
                println("error: invalid amount")
            } else {
                let fb = bal(accts.clone(), from.clone())
                let tb = bal(accts.clone(), to.clone())
                match fb {
                    None => println("error: unknown account ${from}"),
                    Some(f) => {
                        match tb {
                            None => println("error: unknown account ${to}"),
                            Some(t) => {
                                if from == to {
                                    println("error: same account")
                                } else if amt > f {
                                    println("error: insufficient funds")
                                } else {
                                    accts.insert(from, f - amt)
                                    accts.insert(to, t + amt)
                                    println("ok")
                                }
                            }
                        }
                    }
                }
            }
        }
    }
    for (k, v) in accts {
        println("${k} ${v}")
    }
}

